-- migration_032_merge_overlapping_kbs_oct2026.sql
-- Merges overlapping knowledge boxes (batch 16 follow-up). The new batch-16 questions carry the merged boxes via migration_031;
-- this migration replaces the explanation (question text + knowledge box) of four EXISTING questions with the merged box, byte-identical:
--   q_mtf_conventional_tens_001 -> KB "TENS and Gate Control Theory"
--   q_mtf_local_anaesthetic_properties_001 -> KB "Local Anaesthetics"
--   q_mtf_dorsal_horn_cytoarchitecture_001 -> KB "Dorsal Horn, Visceral and Referred Pain"
--   q_mtf_inhibitory_neurotransmitters_pain_001 -> KB "Inhibitory Neurotransmitters and Endogenous Opioid Peptides"
-- Only the knowledge-box portion of each explanation changes; the option A-E text is unchanged. Idempotent (re-running sets the same value).

update questions set data = jsonb_set(data, '{explanation}', to_jsonb($kb$<p>Conventional TENS uses high-frequency, low-intensity stimulation to preferentially activate large-diameter A&beta; fibres, producing analgesia mainly through the spinal gate-control mechanism and opioid-mediated pathways, and understanding its parameters and safety profile is frequently tested.</p>
<p style="margin-top:12px"><strong>A. TRUE</strong> — Conventional TENS typically uses a <strong>high frequency of 50&ndash;100 Hz</strong>, delivered at low intensity, producing a comfortable tingling/buzzing sensation without visible muscle contraction.</p>
<p style="margin-top:12px"><strong>B. FALSE</strong> — The typical pulse <strong>width</strong> (duration) for conventional TENS is in the range of <strong>50&ndash;200 microseconds</strong>, not milliseconds &mdash; this is a common unit-based exam trap; a pulse width of milliseconds would be several orders of magnitude too long and outside standard TENS parameters.</p>
<p style="margin-top:12px"><strong>C. FALSE</strong> — TENS manufacturers list cardiac pacemakers, pregnancy, and epilepsy as contraindications largely because it may be difficult to exclude TENS as a cause of a problem from a legal perspective. In practice, TENS can be used safely in patients with epilepsy; there is no established mechanism by which peripheral transcutaneous electrical stimulation would provoke seizure activity. Recognised contraindications instead include use over the carotid sinus, in patients with cardiac pacemakers/implantable defibrillators, and over the pregnant abdomen.</p>
<p style="margin-top:12px"><strong>D. FALSE</strong> — Conventional TENS does <strong>not</strong> work primarily through GABA modulation; its main proposed mechanisms are the <strong>gate control theory</strong> (activation of large A&beta; fibres inhibiting nociceptive transmission at the dorsal horn) and spinal <strong>delta-opioid receptor</strong> activation.</p>
<p style="margin-top:12px"><strong>E. TRUE</strong> — TENS is contraindicated (or requires specialist caution) in patients with cardiac pacemakers or implantable cardioverter-defibrillators (ICDs), due to the risk of electrical interference with device function; TENS electrodes should also not be placed near the device itself even where cautious use is considered acceptable.</p>
<div style="margin-top:18px"><div style="border:1px solid var(--border-strong);border-radius:14px;overflow:hidden">
  <div style="display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)">
    <span style="font-weight:700;color:#fff;font-size:14.5px">TENS and Gate Control Theory</span>
    <div style="display:inline-flex;align-items:center;gap:7px;flex-shrink:0">
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>
      <span style="font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px">Knowledge</span>
    </div>
  </div>
  <div style="background:var(--surface-warm)"><div style="padding:16px 18px 14px;"><p style="margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)">Transcutaneous Electrical Nerve Stimulation (TENS) is a non-invasive, low-cost, patient-controlled method of pain relief. A small battery-powered pulse generator delivers electrical pulses to the skin through adhesive surface electrodes.</p><p style="margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)">Parameters that can be modified on a TENS machine include pulse duration (in microseconds), pulse frequency (in Hz or pulses/sec) and pulse amplitude (in milliamperes).</p></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Gate Control Theory</div><p style="margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)">Melzack and Wall (1965) proposed that the substantia gelatinosa (lamina II) acts as a &ldquo;gate&rdquo; modulating transmission to the dorsal horn projection (T) neurone. The balance of large-fibre and small-fibre input, together with descending control from the brain, determines whether the gate is open or closed.</p><div style="text-align:center"><img src="images/gate-control-theory.svg" alt="Diagram of the gate control theory: A-beta afferents excite the substantia gelatinosa inhibitory interneuron and the projection T cell; A-delta and C afferents inhibit the interneuron and excite the T cell; descending brain pathways modulate the interneuron; the T cell projects via the spinothalamic tract" style="max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7"></div></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Effect on the Gate</div><table style="margin:0"><tr><th>Input</th><th>Effect on SG inhibitory interneurone</th><th>Effect on T cell</th><th>Net result</th></tr><tr><td>A&beta; (large fibres)</td><td>Excites</td><td>Excites, but also inhibited via interneurone</td><td>Gate closes; less pain transmitted</td></tr><tr><td>A&delta; and C (small fibres)</td><td>Inhibits</td><td>Excites</td><td>Gate opens; more pain transmitted</td></tr><tr><td>Descending brain pathways</td><td>Modulate (usually enhance inhibition)</td><td>Indirect</td><td>Gate closes (attention, expectation, descending inhibition)</td></tr></table><table style="margin:12px 0 0"><tr><th>Application of the gate concept</th><th>Principle</th></tr><tr><td>Rubbing a bruise or shaking a hand after injury</td><td>Everyday recruitment of A&beta; fibres</td></tr><tr><td>Conventional TENS</td><td>Comfortable paraesthesia over the painful area; A&beta; recruitment closes the gate</td></tr><tr><td>Spinal cord stimulation</td><td>Developed from gate control theory; paraesthesia-based SCS stimulates dorsal column A&beta; fibres</td></tr></table><p style="margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)">Modern interpretations place greater emphasis on GABA/glycine-mediated inhibition. Loss of this inhibition (disinhibition) after nerve injury can allow A&beta; input to drive nociceptive circuits, producing mechanical allodynia.</p></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Types of TENS</div><table style="margin:0"><tr><th>Type</th><th>Frequency</th><th>Intensity</th><th>Fibres activated</th><th>Proposed mechanism</th></tr><tr><td><strong>Conventional TENS</strong></td><td>High (~50&ndash;100 Hz)</td><td>Low &mdash; comfortable tingling, no visible contraction</td><td>Large-diameter A&beta; afferents</td><td>Segmental gate-control inhibition of dorsal horn transmission; spinal delta-opioid receptor involvement</td></tr><tr><td><strong>Acupuncture-like TENS (AL-TENS)</strong></td><td>Low (~2&ndash;4 Hz)</td><td>High &mdash; visible muscle twitching</td><td>Smaller A&delta; afferents / motor efferents</td><td>Extrasegmental, opioid-mediated (mu-receptor) analgesia via activation of descending inhibitory pathways</td></tr><tr><td><strong>Intense TENS</strong></td><td>High</td><td>Very high &mdash; at or near the limit of tolerability</td><td>Small-diameter A&delta; (and some C) fibres</td><td>Counter-irritation / hyperstimulation analgesia; typically used briefly for short, painful procedures (e.g. wound dressing changes, injections) rather than continuously, as tolerance to the high intensity limits prolonged application</td></tr></table></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">TENS Contraindications</div><table style="margin:0"><tr><th>Contraindication / precaution</th><th>Reason</th></tr><tr><td>Cardiac implantable devices</td><td>Pacemakers and implantable cardioverter-defibrillators &mdash; electrical interference can disrupt device sensing/pacing.</td></tr><tr><td>Over the carotid sinus</td><td>Risk of provoking a vasovagal/hypotensive response.</td></tr><tr><td>Over the anterior neck / larynx</td><td>Risk of laryngospasm or interference with airway reflexes.</td></tr><tr><td>Pregnancy</td><td>Avoid placement over the abdomen or lower back, particularly in early pregnancy, due to theoretical uterine stimulation risk (direct evidence of harm is limited).</td></tr><tr><td>Active malignancy at the treatment site</td><td>Theoretical concern regarding electrical stimulation of tumour tissue, though evidence is limited.</td></tr><tr><td>Broken/irritated skin, adhesive allergy</td><td>Local skin precautions.</td></tr><tr><td>Driving, operating machinery, or sleep</td><td>Devices should never be applied then, given the reliance on patient feedback for safe intensity titration.</td></tr><tr><td>Dysaesthesia / diminished sensation</td><td>TENS should not be applied to skin with diminished sensation &mdash; nerve damage is likely to reduce effectiveness and the patient may be unaware that high-intensity currents are causing skin irritation. Caution with mechanical allodynia, as TENS may exacerbate the pain.</td></tr></table></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Effectiveness</div><p style="margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)">Clinical experience suggests that TENS may relieve any type of chronic pain, yet systematic reviews are inconclusive for chronic pain, low back pain, cancer-related pain, rheumatoid arthritis of the hand, post-stroke shoulder pain, whiplash and mechanical neck disorders, and chronic recurrent headache. Meta-analyses for osteoarthritic knee pain and for chronic musculoskeletal pain have been more positive, suggesting that TENS is superior to sham TENS for pain and stiffness. Non-randomised controlled clinical trials have found benefit for many types of chronic pain.</p><p style="margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)">NICE guidance does <strong>not</strong> recommend routinely offering TENS for chronic low back pain.</p></div></div>
</div></div>$kb$::text)) where id = 'q_mtf_conventional_tens_001';
update questions set data = jsonb_set(data, '{explanation}', to_jsonb($kb$<p>Beyond their primary sodium-channel-blocking mechanism producing nerve conduction blockade, local anaesthetics have several recognised "non-conventional" pharmacological properties of increasing clinical and research interest, particularly in perioperative and cancer medicine.</p>
<p style="margin-top:12px"><strong>A. TRUE</strong> &mdash; Local anaesthetics show antiviral activity in vitro, thought to relate to membrane-stabilising effects interfering with viral entry and replication, though the clinical significance in practice is limited.</p>
<p style="margin-top:12px"><strong>B. TRUE</strong> &mdash; Local anaesthetics have antibacterial properties against a range of organisms, attributed to disruption of bacterial cell membranes; this underlies interest in their use as an adjunct to prevent catheter-related infection.</p>
<p style="margin-top:12px"><strong>C. TRUE</strong> &mdash; Local anaesthetics have shown anti-metastatic / anti-cancer properties in preclinical studies, potentially via inhibition of cancer cell migration and invasion (voltage-gated sodium channels are expressed by some cancer cell types and implicated in metastatic potential).</p>
<p style="margin-top:12px"><strong>D. TRUE</strong> &mdash; Local anaesthetics have anti-inflammatory effects, including inhibition of neutrophil function (chemotaxis, degranulation, reactive oxygen species release) and modulation of inflammatory cytokine release &mdash; contributing to the benefits seen with techniques such as intravenous lidocaine infusion in enhanced recovery protocols.</p>
<p style="margin-top:12px"><strong>E. TRUE</strong> &mdash; Local anaesthetics have demonstrated antioxidant properties, including scavenging of reactive oxygen species, contributing to some of the proposed organ-protective effects seen in experimental models.</p>
<div style="margin-top:18px"><div style="border:1px solid var(--border-strong);border-radius:14px;overflow:hidden">
  <div style="display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)">
    <span style="font-weight:700;color:#fff;font-size:14.5px">Local Anaesthetics</span>
    <div style="display:inline-flex;align-items:center;gap:7px;flex-shrink:0">
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>
      <span style="font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px">Knowledge</span>
    </div>
  </div>
  <div style="background:var(--surface-warm)"><div style="padding:16px 18px 14px;"><p style="margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)">Local anaesthetics (LAs) are weak bases that reversibly block voltage-gated sodium channels from the intracellular side of the neuronal membrane, preventing sodium influx, action potential propagation, and nerve conduction. To reach this intracellular binding site, the uncharged (lipid-soluble) form must first cross the lipid membrane; a proportion then re-ionises intracellularly to the charged form, which is the active species at the sodium channel.</p></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Ionisation and Site of Action</div><div style="text-align:center"><img src="images/local-anaesthetic-ionisation.svg" alt="Diagram of local anaesthetic action: ionised and un-ionised forms in equilibrium outside the axon, the lipid-soluble base crossing the membrane, re-equilibration inside, and the ionised form blocking the inner pore of the sodium channel" style="max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7"></div></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Classification</div><table style="margin:0"><tr><th>Class</th><th>Examples</th><th>Notes</th></tr><tr><td>Esters</td><td>Cocaine, procaine, tetracaine, chloroprocaine</td><td>Metabolised by plasma cholinesterase; higher allergy potential (PABA metabolite)</td></tr><tr><td>Amides</td><td>Lidocaine, bupivacaine, levobupivacaine, ropivacaine, prilocaine</td><td>Metabolised hepatically; recognised by two "i"s in the name before "-caine"</td></tr></table></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Factors Affecting Clinical Effect</div><table style="margin:0"><tr><th>Factor</th><th>Effect</th></tr><tr><td>pKa (onset)</td><td>pKa is the pH at which 50% of the drug is ionised and 50% unionised. The unionised (lipophilic) form crosses the membrane, so a lower pKa (closer to pH 7.4) gives more unionised drug and a faster onset (e.g. lidocaine, pKa ~7.9, is faster than bupivacaine, ~8.1). In infected / acidic tissue more drug stays ionised, reducing membrane penetration and LA efficacy.</td></tr><tr><td>Lipid solubility (potency)</td><td>Higher lipid solubility &rarr; easier passage through the lipid-rich neuronal membrane &rarr; greater potency.</td></tr><tr><td>Protein binding (duration)</td><td>LAs bind mainly to alpha-1 acid glycoprotein (and albumin). Higher protein binding means the drug stays bound at the sodium channel longer &rarr; longer duration (bupivacaine ~95% bound lasts far longer than lidocaine ~65%).</td></tr><tr><td>Dose / concentration / volume</td><td>A higher total dose increases the concentration gradient driving diffusion into the nerve, affecting onset speed and block density / duration.</td></tr><tr><td>Vasoactivity</td><td>Most LAs (except cocaine, which is vasoconstrictive) cause vasodilation, increasing systemic absorption and shortening local duration. Added adrenaline counteracts this &mdash; prolonging the block and lowering peak plasma concentration by reducing vascular uptake.</td></tr><tr><td>Site of injection</td><td>Highly vascular sites (e.g. intercostal block) &rarr; faster systemic absorption, shorter duration, higher plasma levels. Poorly vascular sites (e.g. subcutaneous) &rarr; slower absorption, longer local duration.</td></tr><tr><td>Fibre type / diameter</td><td>Smaller fibres are generally blocked first (B sympathetic fibres, then C and A&delta; pain and temperature fibres, then A&beta; touch, with A&alpha; motor fibres last), so sympathetic and sensory block precede motor block. See the Peripheral Nerve Fibre Types knowledge box.</td></tr><tr><td>State-dependent (use-dependent) block</td><td>LAs bind with higher affinity to open and inactivated sodium channels than to resting channels, so rapidly firing fibres are blocked preferentially. The resting membrane potential is unchanged: the block raises the firing threshold and slows depolarisation until propagation fails.</td></tr></table></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">pKa and Onset</div><table style="margin:0"><tr><th>Agent</th><th>pKa</th><th>Approx. un-ionised fraction at pH 7.4</th><th>Onset</th></tr><tr><td>Mepivacaine</td><td>7.7</td><td>33%</td><td>Fast</td></tr><tr><td>Lidocaine</td><td>7.9</td><td>24%</td><td>Fast</td></tr><tr><td>Bupivacaine / levobupivacaine</td><td>8.1</td><td>17%</td><td>Intermediate</td></tr><tr><td>Ropivacaine</td><td>8.1</td><td>17%</td><td>Intermediate</td></tr><tr><td>Chloroprocaine</td><td>8.7</td><td>5%</td><td>Fast, because of the high concentration used</td></tr></table><p style="margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)">Fractions calculated from the Henderson&ndash;Hasselbalch equation; published pKa values vary slightly between sources. Adding sodium bicarbonate raises pH, increases the un-ionised fraction and shortens onset.</p></div></div>
</div></div>$kb$::text)) where id = 'q_mtf_local_anaesthetic_properties_001';
update questions set data = jsonb_set(data, '{explanation}', to_jsonb($kb$<p>The dorsal horn is organised into distinct laminae (Rexed laminae I&ndash;VI), each with characteristic afferent input and neuronal types, and this cytoarchitecture underpins how different classes of sensory information are processed and modulated.</p>
<p style="margin-top:12px"><strong>A. FALSE</strong> — Galanin is predominantly <strong>inhibitory/antinociceptive</strong> in the dorsal horn under normal physiological conditions, acting via <strong>GalR1</strong> receptors. Following peripheral nerve injury, galanin expression is markedly upregulated in primary afferents (a classic neuropathic pain marker), and its net effect becomes more complex &mdash; with some pronociceptive contribution via <strong>GalR2</strong> in the injured state &mdash; but as a general statement, galanin is not classified as excitatory.</p>
<p style="margin-top:12px"><strong>B. FALSE</strong> — Most nociceptive primary afferents (A&delta; and C fibres) terminate in the <strong>superficial dorsal horn &mdash; laminae I and II</strong>, not laminae III&ndash;V. Laminae III&ndash;V receive predominantly non-nociceptive (A&beta;, low-threshold mechanoreceptor) input, though lamina V does contain wide dynamic range neurons that also receive convergent nociceptive input.</p>
<p style="margin-top:12px"><strong>C. FALSE</strong> — Wide dynamic range (WDR) neurons, found mainly in lamina V, are defined precisely by receiving <strong>convergent input from both nociceptive (A&delta;, C fibre) and non-nociceptive (A&beta;, low-threshold) afferents</strong> &mdash; this convergence is the basis of their name and their proposed role in phenomena like referred pain and temporal summation ("wind-up").</p>
<p style="margin-top:12px"><strong>D. TRUE</strong> — Lamina II (<strong>substantia gelatinosa</strong>) predominantly receives unmyelinated <strong>C-fibre</strong> input (along with some A&delta; input), and contains densely packed interneurons important in local modulation of nociceptive transmission, including the "gate control" mechanism.</p>
<p style="margin-top:12px"><strong>E. TRUE</strong> — Lamina I (marginal zone) contains <strong>nociceptive-specific neurons</strong>, which respond selectively to noxious stimuli and receive input mainly from A&delta; and C fibres, projecting via the spinothalamic tract to supraspinal pain-processing centres.</p>
<div style="margin-top:18px"><div style="border:1px solid var(--border-strong);border-radius:14px;overflow:hidden">
  <div style="display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)">
    <span style="font-weight:700;color:#fff;font-size:14.5px">Dorsal Horn, Visceral and Referred Pain</span>
    <div style="display:inline-flex;align-items:center;gap:7px;flex-shrink:0">
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>
      <span style="font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px">Knowledge</span>
    </div>
  </div>
  <div style="background:var(--surface-warm)"><div style="padding:16px 18px 14px;"><p style="margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)">Pain primary afferents enter the dorsal horn of the spinal cord, synapsing ipsilaterally with 2nd order neurons. In cross section, the spinal cord resembles an oval of white matter (myelinated axons), surrounding an H-shaped centre of grey matter (cell bodies). The grey matter is arranged into ten histological layers, or laminae, based on cytological architecture, known as Rexed's laminae. The dorsal horn is made up of laminae I&ndash;V.</p></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Rexed Laminae</div><div style="text-align:center"><img src="images/rexed-laminae.png" alt="Rexed laminae — spinal cord grey matter cross-section with laminae I–X labelled alongside a table of regions, nuclei and corresponding laminae" style="max-width:100%;border-radius:10px;margin-top:0;border:1px solid #EDE3D7"></div></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Primary Afferent Termination</div><p style="margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)">A&delta; primary afferents terminate on laminae I and V, and C fibres terminate on lamina II, the substantia gelatinosa. A&delta; primary afferents synapse directly with secondary afferents that will eventually carry the pain signal to the thalamus. C fibres do not synapse directly with secondary afferents, but connect instead with interneurons that carry the signal on to secondary afferents in laminae I or V. These interneurons are important in modulation of the pain signal.</p><p style="margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)">Visceral input differs in that fewer primary afferents activate a larger number of second order neurons, resulting in poorer localisation of pain. Visceral afferents also converge with somatic inputs, which may account for the phenomenon of referred pain.</p></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Convergence&ndash;Projection</div><div style="text-align:center"><img src="images/referred-pain-convergence.svg" alt="Diagram of convergence-projection theory: visceral afferent from the heart and somatic afferent from the left arm converge on the same second-order dorsal horn neurone and project via the spinothalamic tract, so pain is perceived in the arm" style="max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7"></div></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Visceral Versus Somatic Pain</div><table style="margin:0"><tr><th>Feature</th><th>Visceral pain</th><th>Somatic pain</th></tr><tr><td>Quality</td><td>Dull, aching, cramping, colicky</td><td>Sharp, well defined</td></tr><tr><td>Localisation</td><td>Poor, often midline</td><td>Good, at site of injury</td></tr><tr><td>Adequate stimulus</td><td>Distension, traction, ischaemia, spasm, inflammation</td><td>Cutting, burning, pressure</td></tr><tr><td>Accompanying features</td><td>Autonomic: nausea, sweating, pallor</td><td>Few</td></tr><tr><td>Referral</td><td>Common, to somatic structures of the same segment</td><td>Uncommon</td></tr><tr><td>Afferent route</td><td>Sympathetic (mainly), vagal, pelvic parasympathetic</td><td>Spinal nerves</td></tr></table></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Common Referral Patterns</div><table style="margin:0"><tr><th>Organ</th><th>Spinal segments</th><th>Referred site</th></tr><tr><td>Heart</td><td>T1&ndash;T4</td><td>Central chest, left arm, jaw</td></tr><tr><td>Diaphragm (central)</td><td>C3&ndash;C5</td><td>Shoulder tip</td></tr><tr><td>Gallbladder</td><td>T7&ndash;T9</td><td>Right subscapular region, right shoulder</td></tr><tr><td>Pancreas</td><td>T6&ndash;T10</td><td>Epigastrium radiating to the back</td></tr><tr><td>Appendix</td><td>T10</td><td>Periumbilical, later localising to the right iliac fossa when the parietal peritoneum is involved</td></tr><tr><td>Kidney and ureter</td><td>T10&ndash;L1</td><td>Loin radiating to the groin and genitalia</td></tr></table><p style="margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)">Approximate segmental levels; individual variation is common. Hyperalgesia and muscle tenderness in the referred area are well described.</p></div></div>
</div></div>$kb$::text)) where id = 'q_mtf_dorsal_horn_cytoarchitecture_001';
update questions set data = jsonb_set(data, '{explanation}', to_jsonb($kb$<p>Inhibitory control of pain transmission in the CNS occurs both segmentally (within the spinal cord dorsal horn) and via descending pathways from supraspinal centres, involving several distinct neurotransmitter systems.</p>
<p style="margin-top:12px"><strong>A. TRUE</strong> — Although generally an excitatory neurotransmitter, acetylcholine is inhibitory within the pain pathway, acting mainly via muscarinic receptors (particularly M2/M4 subtypes) in the dorsal horn and supraspinally (e.g. periaqueductal grey). It has an antinociceptive/inhibitory effect on pain transmission &mdash; the pharmacological basis for the analgesic effect of intrathecal/epidural neostigmine (an acetylcholinesterase inhibitor that raises synaptic ACh levels).</p>
<p style="margin-top:12px"><strong>B. TRUE</strong> — Glycine is a major segmental inhibitory neurotransmitter in the dorsal horn, acting on glycine receptors (ligand-gated chloride channels) to hyperpolarise second-order neurons and inhibit nociceptive transmission; glycinergic disinhibition is implicated in mechanical allodynia.</p>
<p style="margin-top:12px"><strong>C. TRUE</strong> — GABA is a principal segmental inhibitory neurotransmitter in the dorsal horn, acting on GABA-A (ionotropic, fast) and GABA-B (metabotropic, slower) receptors to inhibit nociceptive transmission; loss of GABAergic tone is implicated in central sensitisation.</p>
<p style="margin-top:12px"><strong>D. FALSE</strong> — Glutamate is the principal <strong>excitatory</strong> neurotransmitter of the pain pathway, acting on NMDA, AMPA, and kainate receptors on dorsal horn neurons to mediate fast excitatory nociceptive transmission &mdash; the opposite of inhibitory.</p>
<p style="margin-top:12px"><strong>E. TRUE</strong> — Noradrenaline, released via descending pathways from the locus coeruleus, acts on alpha-2 adrenoreceptors on dorsal horn neurons and primary afferent terminals to inhibit nociceptive transmission &mdash; the pharmacological basis for the analgesic effects of clonidine and dexmedetomidine. Noradrenaline is generally an excitatory neurotransmitter but is inhibitory within the context of the pain pathway.</p>
<div style="margin-top:18px"><div style="border:1px solid var(--border-strong);border-radius:14px;overflow:hidden">
  <div style="display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)">
    <span style="font-weight:700;color:#fff;font-size:14.5px">Inhibitory Neurotransmitters and Endogenous Opioid Peptides</span>
    <div style="display:inline-flex;align-items:center;gap:7px;flex-shrink:0">
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>
      <span style="font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px">Knowledge</span>
    </div>
  </div>
  <div style="background:var(--surface-warm)"><div style="padding:16px 18px 14px;"><p style="margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)">Pain transmission in the dorsal horn is restrained by inhibitory transmitters released from local interneurones and descending pathways. The endogenous opioid peptides are among them; each family is cleaved from its own precursor, and they are released in response to stress and noxious stimulation.</p></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Inhibitory Neurotransmitters in the Pain Pathway</div><table style="margin:0"><tr><th colspan="3" style="text-align:center">Inhibitory neurotransmitters in the pain pathway</th></tr><tr><td><strong>Neurotransmitter</strong></td><td><strong>Full name(s)</strong></td><td><strong>Receptor in dorsal horn</strong></td></tr><tr><td><strong>GABA</strong></td><td>Gamma-aminobutyric acid</td><td>GABA<sub>A</sub>, GABA<sub>B</sub></td></tr><tr><td><strong>Gly</strong></td><td>Glycine</td><td>Glycine (strychnine-sensitive)</td></tr><tr><td><strong>Endorphins</strong></td><td>&beta;-endorphins</td><td>Opioid (&mu;&gt;&delta;,&kappa;)</td></tr><tr><td><strong>Enkephalins</strong></td><td>Met- and Leu-enkephalin, Enk-8</td><td>Opioid (&delta;&gt;&mu;,&kappa;)</td></tr><tr><td><strong>Dynorphins</strong></td><td>Dynorphin-A, Dynorphin-B</td><td>Opioid (&kappa;&gt;&mu;,&delta;)</td></tr><tr><td><strong>Endocannabinoids</strong></td><td>Anandamide (AEA), 2-arachidonoylglycerol (2-AG)</td><td>CB<sub>1</sub></td></tr><tr><td><strong>5-HT</strong></td><td>5-hydroxytryptamine (serotonin)</td><td>5-HT receptor subtypes 1&ndash;3</td></tr><tr><td><strong>NA</strong></td><td>Noradrenaline</td><td>&alpha;<sub>2</sub>-adrenergic</td></tr></table></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Endogenous Opioid Peptides and Precursors</div><table style="margin:0"><tr><th>Peptide</th><th>Precursor</th><th>Notes</th></tr><tr><td>&beta;-endorphin</td><td>Pro-opiomelanocortin (POMC)</td><td>Released with ACTH from the pituitary, and from hypothalamic arcuate neurones; also released by immune cells in inflamed tissue</td></tr><tr><td>Met- and Leu-enkephalin</td><td>Proenkephalin</td><td>Widespread: dorsal horn interneurones, periaqueductal grey, rostral ventromedial medulla, adrenal medulla</td></tr><tr><td>Dynorphins A and B</td><td>Prodynorphin</td><td>Dorsal horn, hypothalamus; implicated in dysphoria; may be pro-nociceptive in chronic pain states</td></tr><tr><td>Endomorphin-1 and -2</td><td>No classical precursor identified</td><td>Highly selective &mu; agonists found in brainstem and spinal cord</td></tr><tr><td>Nociceptin/orphanin FQ</td><td>Pronociceptin</td><td>Acts at the NOP receptor, not blocked by naloxone; supraspinal anti-opioid and spinal analgesic actions</td></tr></table></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Roles in Pain Modulation</div><table style="margin:0"><tr><th>Site or setting</th><th>Role</th></tr><tr><td>Periaqueductal grey and rostral ventromedial medulla</td><td>Opioid peptides inhibit GABAergic interneurones, disinhibiting descending pathways that suppress dorsal horn transmission</td></tr><tr><td>Dorsal horn</td><td>Enkephalinergic interneurones inhibit release from primary afferents and excitability of projection neurones</td></tr><tr><td>Peripheral inflamed tissue</td><td>Immune cells release &beta;-endorphin and enkephalins that act on peripheral opioid receptors on nociceptor terminals</td></tr><tr><td>Stress and exercise</td><td>Release of &beta;-endorphin and enkephalins contributes to stress-induced analgesia; effects are naloxone-reversible</td></tr></table></div></div>
</div></div>$kb$::text)) where id = 'q_mtf_inhibitory_neurotransmitters_pain_001';
